/// Tails one agent session's transcript JSONL: initial bounded backfill,
/// incremental parsing on file growth, an in-memory message cache for
/// history paging, and append/update batches for live push.
///
/// Seq stability: `seq` equals the absolute transcript line index. The
/// initial backfill may skip a long head (bounded memory), in which case
/// pages before the cache report `hasMore` honestly.
actor AgentChatTranscriptTailer {
    /// A live transcript change: newly appended messages and in-place
    /// updates (tool results that completed earlier messages).
    struct Batch: Sendable {
        /// Messages newly appended, ascending seq.
        let appended: [ChatMessage]
        /// Earlier messages re-emitted with their results filled in.
        let updated: [ChatMessage]
        /// First user prompt text, when it just became known.
        let discoveredTitle: String?
        /// The transcript was truncated/replaced and the seq space
        /// restarted; clients must re-anchor.
        var didReset = false
    }

    private let sessionID: String
    private let agentKind: ChatAgentKind
    private let path: String
    private let onBatch: @Sendable (Batch) async -> Void

    private let maxInitialLines: Int
    private let maxCachedMessages: Int

    private var cache: [ChatMessage] = []
    private var parseState = ChatTranscriptParseState()
    private var byteOffset: UInt64 = 0
    private var lineCount = 0
    /// Identity (inode) of the file last read, so an atomic replace /
    /// rotation is detected even when the new file is the same size or
    /// larger (seeking to the old offset would otherwise skip its head).
    private var fileInode: UInt64?
    private var pendingFragment = Data()
    private var headTruncated = false
    private var watchTask: Task<Void, Never>?
    private var watcher: FileWatcher?
    private var started = false
    private var reportedTitle = false

    /// Creates a tailer.
    ///
    /// - Parameters:
    ///   - sessionID: The session this transcript belongs to.
    ///   - agentKind: Selects the parser (claude or codex).
    ///   - path: Absolute transcript JSONL path.
    ///   - maxInitialLines: Backfill bound for the first read.
    ///   - maxCachedMessages: In-memory cache cap; oldest fall out.
    ///   - onBatch: Receives live change batches after the initial load.
    init(
        sessionID: String,
        agentKind: ChatAgentKind,
        path: String,
        maxInitialLines: Int = 2000,
        maxCachedMessages: Int = 4000,
        onBatch: @escaping @Sendable (Batch) async -> Void
    ) {
        self.sessionID = sessionID
        self.agentKind = agentKind
        self.path = path
        self.maxInitialLines = maxInitialLines
        self.maxCachedMessages = maxCachedMessages
        self.onBatch = onBatch
    }

    /// Performs the initial backfill (idempotent) and starts watching for
    /// growth.
    func start() async {
        guard !started else { return }
        started = true
        loadInitialTail()
        let watcher = FileWatcher(path: path, throttle: .milliseconds(200))
        self.watcher = watcher
        watchTask = Task { [weak self] in
            for await _ in watcher.events {
                guard let self else { return }
                await self.drainNewContent()
            }
        }
    }

/// A live update to one session's conversation, pushed by the host.
public enum ChatSessionEvent: Sendable, Equatable {
    /// New messages were appended to the transcript tail.
    case appended([ChatMessage])
    /// Previously-delivered messages changed in place (a tool result
    /// arrived, a permission request was resolved). Receivers replace by
    /// ``ChatMessage/id``.
    case updated([ChatMessage])
    /// The session's live activity state changed.
    case stateChanged(ChatAgentState)
    /// The session's descriptor changed (title, terminal binding, ...).
    case descriptorChanged(ChatSessionDescriptor)
    /// The producing host removed this session from its live registry.
    case sessionRemoved(version: Int)

    /// Terminal command-blocks were appended or updated (terminal-kind
    /// sessions). Receivers upsert by ``TerminalCommandBlock/id``; the
    /// producer sends the whole current block value, so a replayed block on
    /// reconnect is idempotent.
    case terminalBlocks([TerminalCommandBlock])

    /// A live, not-yet-committed preview of the agent's in-progress prose for
    /// the current turn, scraped from the terminal's rendered screen while the
    /// authoritative JSONL line has not been written yet. The payload replaces
    /// any prior preview wholesale; `nil` clears it. It lives outside the
    /// message window and is superseded the instant the authoritative agent
    /// prose lands via ``appended``, so it never duplicates a real message.
    case streamingProse(ChatMessage?)

    /// The producing transcript was truncated or replaced; the session's
    /// seq space restarted and clients must re-anchor from history.
    case reset

    /// An event name this client predates; carried (not dropped) so
    /// consumers can ignore it explicitly.
    case unknown(String)
}

extension ChatSessionEvent: Codable {
    private enum CodingKeys: String, CodingKey {
        case event
        case messages
        case message
        case state
        case descriptor
        case blocks
        case version
    }

    private enum EventName: String {
        case appended
        case updated
        case stateChanged = "state_changed"
        case descriptorChanged = "descriptor_changed"
        case sessionRemoved = "session_removed"
        case terminalBlocks = "terminal_blocks"
        case streamingProse = "streaming_prose"
        case reset
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let raw = try container.decode(String.self, forKey: .event)
        switch EventName(rawValue: raw) {
        case .appended:
            self = .appended(try container.decode([ChatMessage].self, forKey: .messages))
        case .updated:
            self = .updated(try container.decode([ChatMessage].self, forKey: .messages))
        case .stateChanged:
            self = .stateChanged(try container.decode(ChatAgentState.self, forKey: .state))
        case .descriptorChanged:
            self = .descriptorChanged(try container.decode(ChatSessionDescriptor.self, forKey: .descriptor))
        case .sessionRemoved:
            self = .sessionRemoved(version: try container.decodeIfPresent(Int.self, forKey: .version) ?? Int.max)
        case .terminalBlocks:
            self = .terminalBlocks(try container.decode([TerminalCommandBlock].self, forKey: .blocks))
        case .streamingProse:
            self = .streamingProse(try container.decodeIfPresent(ChatMessage.self, forKey: .message))
        case .reset:
            self = .reset

        let agentSpecs = sessionsListAgentSpecs()
        let selectedSpecs: [SessionListAgentSpec]
        if let agentRaw {
            let normalized = agentRaw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            guard !normalized.isEmpty else {
                throw CLIError(message: String(localized: "cli.sessions.error.agentRequiresValue", defaultValue: "sessions list: --agent requires a value"))
            }
            if normalized == "claude" || normalized == "claude-code" || normalized == "claude_code" {
                selectedSpecs = agentSpecs.filter { $0.name == "claude" }
            } else if let def = Self.agentDef(named: normalized) {
                selectedSpecs = agentSpecs.filter { $0.name == def.name }
            } else {
                throw CLIError(message: String(
                    format: String(localized: "cli.sessions.error.unknownAgent", defaultValue: "sessions list: unknown agent '%@'"),
                    agentRaw
                ))
            }
        } else {
            selectedSpecs = agentSpecs
        }

        let sessionFilter = sessionsListNormalized(sessionRaw)?.lowercased()
        let workspaceFilter = sessionsListNormalizedIDRef(workspaceRaw)?.lowercased()
        let surfaceFilter = sessionsListNormalizedIDRef(surfaceRaw)?.lowercased()
        let cwdFilter = sessionsListNormalized(cwdRaw)?.lowercased()
        let hasRecordFilter = sessionFilter != nil || workspaceFilter != nil || surfaceFilter != nil || cwdFilter != nil
        var codexIndexes: [String: CodexSessionListIndex] = [:]
        let claudeTranscriptLookup = SessionsListClaudeTranscriptLookupCache(homeDirectory: homeDirectory)
        var entries: [SessionListEntry] = []
        var stores: [[String: Any]] = []

        let decoder = JSONDecoder()
        for spec in selectedSpecs {
            let storePath = URL(fileURLWithPath: stateDir, isDirectory: true)
                .appendingPathComponent("\(spec.sessionStoreSuffix)-hook-sessions.json", isDirectory: false)
                .path
            var storePayload: [String: Any] = [
                "agent": spec.name,
                "path": storePath,
                "exists": fileManager.fileExists(atPath: storePath)
            ]

            guard fileManager.fileExists(atPath: storePath) else {
                storePayload["session_count"] = 0
                stores.append(storePayload)
                continue
            }

            let storeData = try Data(contentsOf: URL(fileURLWithPath: storePath))
            let store = try decoder.decode(ClaudeHookSessionStoreFile.self, from: storeData)
            storePayload["session_count"] = store.sessions.count
            stores.append(storePayload)

            for rawRecord in store.sessions.values {
                let record = spec.name == "claude"
                    ? sessionsListResolvedClaudeWorkflowRecord(rawRecord, lookup: claudeTranscriptLookup)
                    : rawRecord
                let rawSessionId = rawRecord.sessionId.lowercased()
                let resolvedSessionId = record.sessionId.lowercased()
                guard sessionFilter == nil || rawSessionId == sessionFilter || resolvedSessionId == sessionFilter else {
                    continue
                }
                guard workspaceFilter == nil || record.workspaceId.lowercased() == workspaceFilter else { continue }
                guard surfaceFilter == nil || record.surfaceId.lowercased() == surfaceFilter else { continue }
                if let cwdFilter {
                    let cwd = (record.cwd ?? "").lowercased()
                    let launchCwd = (record.launchCommand?.workingDirectory ?? "").lowercased()
                    guard cwd.contains(cwdFilter) || launchCwd.contains(cwdFilter) else { continue }
                }

                var payload: [String: Any] = [
                    "agent": spec.name,
                    "agent_display_name": spec.displayName,
                    "session_id": record.sessionId,
                    "workspace_id": record.workspaceId,
                    "surface_id": record.surfaceId,
                    "store_path": storePath,
                    "started_at": sessionsListTimestamp(record.startedAt),
                    "updated_at": sessionsListTimestamp(record.updatedAt),
                    "updated_at_unix": record.updatedAt
                ]
                if rawRecord.sessionId != record.sessionId {
                    payload["hook_session_id"] = rawRecord.sessionId
                }
                payload["cwd"] = record.cwd ?? NSNull()
                payload["transcript_path"] = record.transcriptPath ?? NSNull()
                payload["pid"] = record.pid ?? NSNull()
                payload["runtime_status"] = record.runtimeStatus?.rawValue ?? NSNull()
                payload["agent_lifecycle"] = record.agentLifecycle?.rawValue ?? NSNull()
                payload["last_prompt_turn_id"] = record.lastPromptTurnId ?? NSNull()
=== usage ===
        }
        if sortedEntries.count > limitedEntries.count {
            print(String(
                format: String(localized: "cli.sessions.output.more", defaultValue: "... %lld more. Pass --all or --limit <n>."),
                sortedEntries.count - limitedEntries.count
            ))
